  const tone=audioCtx.createOscillator(),level=audioCtx.createGain(),lowpass=audioCtx.createBiquadFilter();
  tone.type='sine';tone.frequency.setValueAtTime(down?410:350,start);tone.frequency.exponentialRampToValueAtTime(down?250:220,start+.047);
  lowpass.type='lowpass';lowpass.frequency.value=670;
