  if(Math.abs(z-state.lateral)<2.25)continue;
  // Leave the whole approach and passing corridor free. Never drive through other AI.
  if(!forced&&!rearPlanClear(lane))continue;
  const cruise=Math.min(245,Math.max(205,state.speed+58)+hash(seed+5)*7);
