const REAR_WORDS={title:{left:L("BLIS · 左後方快速來車"),right:L("BLIS · 右後方快速來車")},detail:L("請維持原車道，注意側後方超車")};
// V8.16: an amber BLIS indicator stays on for the entire approach and blind-spot passage.
// It is associated with a REAL AI vehicle (same id, x, and lane), not a camera animation.
function updateRearApproach(){
 state.rearApproach=null;
 if(state.mode!=='highway'||state.run!=='running'||state.score<4000)return;
 let chosen=null,soon=Infinity;
 for(const tr of state.traffic){
  if(!tr.isRearOvertaker||tr.x>20||tr.x< -58)continue;
  const closing=(tr.speed-state.speed)/3.6;
  if(closing<1.0&&tr.x<0)continue;
  const eta=Math.max(0,-tr.x/Math.max(0.1,closing));
  if((eta<=3.1||tr.x>=-22)&&eta<soon){chosen=tr;soon=eta;}
 }
 if(!chosen)return;
 const side=chosen.z<state.lateral?'left':'right';
 state.rearApproach={id:chosen.id,side,eta:soon,x:chosen.x};
 if(state.blis&&!chosen.approachNotified){
  chosen.approachNotified=true;
  textEvent(REAR_WORDS.title[side],REAR_WORDS.detail,'',1.35);
  safetyChime('blis');
 }
}
function spawnMoose(){const dir=hash(state.wave+state.elapsed)>.5?1:-1;state.moose={x:88,z:dir*7.3,dir,run:3.2,passed:false};state.mooseCountdown=32+32*hash(state.wave*7);textEvent(L("⚠ 前方麋鹿突發！"),L("請減速並安全避讓"),'alert mooseAlert',3.3);try{navigator.vibrate?.([90,40,110])}catch(e){}}
