function sphereGeometry(segments=22,rings=12){const v=[],idx=[];for(let j=0;j<=rings;j++){const phi=Math.PI*j/rings;for(let i=0;i<=segments;i++){const th=i*2*Math.PI/segments;const x=Math.sin(phi)*Math.cos(th),y=Math.cos(phi),z=Math.sin(phi)*Math.sin(th);v.push(x,y,z,x,y,z)}}for(let j=0;j<rings;j++)for(let i=0;i<segments;i++){const a=j*(segments+1)+i,b=a+segments+1;idx.push(a,b,a+1,b,b+1,a+1)}return createGeometry(new Float32Array(v),new Uint32Array(idx))}
