 const carW=Math.min(W*.49,255),carH=carW*.61,carX=W/2-carW/2+(state.mode==='highway'?state.lateral*W*.10:0),cy=H*.69;ctx.fillStyle='#0a1e2488';ctx.beginPath();ctx.ellipse(carX+carW/2,cy+carH*.8,carW*.38,12,0,0,Math.PI*2);ctx.fill();if(backupCar.complete&&backupCar.naturalWidth)ctx.drawImage(backupCar,carX,cy,carW,carH);else{ctx.fillStyle='#d5e7e9';ctx.fillRect(carX+20,cy,carW-40,carH)}
