let last=performance.now(),lastUi=0,spin=0;function frame(ts){const dt=clamp((ts-last)/1000,0,.06);last=ts;advance(dt);
 // High spoke-frequency at 100 km/h can alias to a stationary rim at 60 fps.
  // Keep visually observable rotation (not a physical wheel-RPM measurement) and wrap the angle.
  const physicalOmega=state.speed/(3.6*.34);
  const visualOmega=physicalOmega/(1+physicalOmega/30);
  if(state.mode!=='showroom')spin=(spin+visualOmega*dt)%(Math.PI*2);
  try{if(graphics)graphics.drawWorld(ts,spin);else draw2D()}catch(e){if(!$('fallbackNote').dataset.err){$('fallbackNote').style.display='block';$('fallbackNote').textContent=L("3D 畫面錯誤：")+e.message;$('fallbackNote').dataset.err='1'}}if(ts-lastUi>45){updateUI();lastUi=ts}requestAnimationFrame(frame)}
setMode('highway');syncAssistButtons();requestAnimationFrame(frame);
